style.css:
@-moz-document domain("roblox.com") {
body, html {
    background-color: #1e1e1e !important;
    color: #ffffff !important;
  }

  /* Fondo de la mayoría de los paneles */
  .content, .container, .section, .rbx-header, .game-card-container {
    background-color: #2a2a2a !important;
  }

  /* Texto más claro */
  .text-label, .text-overflow, .game-card-name, .section-header {
    color: #ffffff !important;
  }

  /* Botones y cuadros */
  button, input, textarea {
    background-color: #333333 !important;
    color: #ffffff !important;
    border: 1px solid #555555 !important;
  }

  /* Ocultar anuncios si querés */
  .abp, .ad-container {
    display: none !important;
  }
}
